query:
query EpicFDefinitionsAndRoutes {
 productDefinitions: metafieldDefinitions(first: 50, ownerType: PRODUCT) { nodes { id namespace key type { name } } pageInfo { hasNextPage endCursor } }
 metaobjectDefinitions(first: 50) { nodes { id type } pageInfo { hasNextPage endCursor } }
 pages(first: 50) { nodes { id handle title body publishedAt updatedAt } pageInfo { hasNextPage endCursor } }

}
